css:
:root { --capri-heading: #FF8FB0; --capri-emphasis: #6EE7A4; --capri-bright: #08F868; --capri-line: #0E8F4E; --capri-red: #FA0F46; --capri-chip: #0B2E1E; }
:root:not(.dark) { --capri-heading: #A3154A; --capri-emphasis: #05472C; --capri-bright: #0B7A4B; --capri-line: #0B7A4B; --capri-red: #FA0F46; --capri-chip: #D8F5E5; }
[data-user-message-bubble] { border: 1px solid var(--capri-red); border-radius: 2px !important; box-shadow: 3px 3px 0 var(--capri-red); }
.chat-markdown h1, .chat-markdown h2, .chat-markdown h3, .chat-markdown h4, .chat-markdown th { color: var(--capri-heading) !important; }
.chat-markdown strong { color: var(--capri-emphasis) !important; }
.chat-markdown a { color: var(--capri-emphasis) !important; text-decoration-color: var(--capri-red) !important; }
.chat-markdown li::marker { color: var(--capri-bright); }
.chat-markdown :not(pre) > code { color: var(--capri-emphasis) !important; background: var(--capri-chip) !important; border-radius: 2px !important; }
.chat-markdown blockquote { border-left-color: var(--capri-bright) !important; }
.chat-markdown hr { border-color: var(--capri-line) !important; }
.chat-markdown-codeblock { border-left: 2px solid var(--capri-bright); border-radius: 2px !important; box-shadow: 3px 3px 0 var(--capri-red); }
[data-slot="composer-host"] { border-color: var(--capri-line) !important; border-radius: 3px !important; box-shadow: 4px 4px 0 var(--capri-red); }
[data-slot="composer-shell"]::before, [data-slot="composer-host"]::before, [data-slot="composer-host"]::after, [data-chat-composer-main-surface], [data-chat-composer-main-surface]::after { border-radius: 3px !important; }
[data-chat-composer-surface] { border-radius: 2px !important; }
[data-slot="button"], [data-slot="input"], [data-slot="select-trigger"], [data-slot="menu-popup"], [data-slot="popover-popup"], [data-slot="dialog-popup"], [data-slot="tooltip-popup"], [data-thread-item] { border-radius: 2px !important; }
::-webkit-scrollbar-thumb { background: var(--capri-line); }
::-webkit-scrollbar-thumb:hover { background: var(--capri-bright); }
svg.lucide { stroke-linecap: square; stroke-linejoin: miter; }
[data-slot="sidebar"] { --app-theme-secondary-label: var(--capri-heading); --secondary-label: var(--capri-heading); --contrast-secondary-label: var(--capri-heading); --app-theme-icon-muted: var(--capri-heading); --icon-muted: var(--capri-heading); --contrast-icon-muted: var(--capri-heading); }
[data-slot="sidebar"] .text-secondary-label, [data-slot="sidebar"] .text-icon-muted { color: var(--capri-heading) !important; }
